CREATE OR REPLACE FUNCTION private.garde_acte()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                               declare r text := (select private.my_role());
                                                                                                                                                                                               begin
                                                                                                                                                                                                 new.updated_at:=now();
                                                                                                                                                                                                   if old.statut in ('signe','transmis','publie','archive') and (to_jsonb(new)-'{statut,date_transmission,preuve_transmission,observations,updated_at}'::text[]) is distinct from (to_jsonb(old)-'{statut,date_transmission,preuve_transmission,observations,updated_at}'::text[]) then
                                                                                                                                                                                                       raise exception 'Un acte signé ne peut plus être modifié'; end if;
                                                                                                                                                                                                         if new.statut is distinct from old.statut then
                                                                                                                                                                                                             if new.statut='validation' and old.statut not in ('brouillon','preparation') then raise exception 'Statut invalide'; end if;
                                                                                                                                                                                                                 if new.statut='signe' then
                                                                                                                                                                                                                       if old.statut<>'validation' then raise exception 'L’acte doit être soumis à validation avant signature'; end if;
                                                                                                                                                                                                                             if r is not null and r not in ('maire','super_admin') then raise exception 'La signature est réservée à l’autorité signataire (le maire)'; end if;
                                                                                                                                                                                                                                   if new.preuve_signature is null or new.date_signature is null or coalesce(new.signataire,'')='' then raise exception 'Un acte n’est signé qu’avec la preuve de signature, la date et l’autorité signataire'; end if; end if;
                                                                                                                                                                                                                                       if new.statut='transmis' then
                                                                                                                                                                                                                                             if old.statut<>'signe' then raise exception 'L’acte doit être signé avant d’être transmis'; end if;
                                                                                                                                                                                                                                                   if new.date_transmission is null then raise exception 'Renseignez la date de transmission'; end if; end if;
                                                                                                                                                                                                                                                       if new.statut='publie' and old.statut not in ('signe','transmis') then raise exception 'Seul un acte signé peut être publié ou notifié'; end if;
                                                                                                                                                                                                                                                           if new.statut='archive' and old.statut not in ('signe','transmis','publie') then raise exception 'Seul un acte signé peut être archivé'; end if;
                                                                                                                                                                                                                                                             end if;
                                                                                                                                                                                                                                                               return new; end $function$

CREATE OR REPLACE FUNCTION private.garde_courrier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                         declare r text := (select private.my_role());
                         begin
                           new.updated_at:=now();
                             if new.sens is distinct from old.sens then raise exception 'Le sens du courrier est immuable'; end if;
                               if new.categorie='Correspondance confidentielle' then new.confidentiel:=true; end if;
                                 if old.statut='archive' and r is not null and r not in ('maire','super_admin') then raise exception 'Courrier archivé : non modifiable'; end if;
                                   if new.sens='out' then
                                       if old.statut in ('signe','envoye','archive') and (to_jsonb(new)-'{statut,date_envoi,mode_transmission,preuve_envoi,pieces,observations,updated_at}'::text[]) is distinct from (to_jsonb(old)-'{statut,date_envoi,mode_transmission,preuve_envoi,pieces,observations,updated_at}'::text[]) then
                                             raise exception 'Un courrier signé ne peut plus être modifié'; end if;
                                                 if new.statut is distinct from old.statut then
                                                       if new.statut='en_validation' and old.statut<>'brouillon' then raise exception 'Seul un brouillon peut être soumis à validation'; end if;
                                                             if new.statut='valide' then
                                                                     if old.statut<>'en_validation' then raise exception 'Le courrier doit d’abord être soumis à validation'; end if;
                                                                             if r is not null and r not in ('maire','adjoint','super_admin') then raise exception 'La validation est réservée au maire ou à l’adjoint'; end if;
                                                                                     new.valide_par:=(select auth.uid()); new.valide_le:=now(); end if;
                                                                                           if new.statut='signe' then
                                                                                                   if old.statut<>'valide' then raise exception 'Le courrier doit être validé avant d’être signé'; end if;
                                                                                                           if r is not null and r not in ('maire','super_admin') then raise exception 'La signature est réservée au maire'; end if;
                                                                                                                   if cardinality(new.pieces)=0 then raise exception 'Joignez la copie signée comme preuve de signature'; end if;
                                                                                                                           new.signe_par:=(select auth.uid()); new.signe_le:=now(); end if;
                                                                                                                                 if new.statut='envoye' then
                                                                                                                                         if old.statut<>'signe' then raise exception 'Le courrier doit être signé avant l’envoi'; end if;
                                                                                                                                                 if new.date_envoi is null or new.mode_transmission is null then raise exception 'Renseignez la date et le mode de transmission'; end if; end if;
                                                                                                                                                     end if;
                                                                                                                                                       end if;
                                                                                                                                                         return new; end $function$

CREATE OR REPLACE FUNCTION private.garde_deleg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text := (select private.my_role());
begin
  new.updated_at:=now();
  if r is not null and r not in ('maire','super_admin') then raise exception 'Seul le maire peut modifier une délégation'; end if;
  if new.statut='effective' then
    if new.acte is null or new.date_debut is null then raise exception 'Une délégation devient effective seulement avec l’acte officiel enregistré et une date de début'; end if;
    if tg_op='INSERT' or old.statut is distinct from 'effective' then new.valide_par:=(select auth.uid()); new.valide_le:=now();
      perform private.notifier_adjoint(new.commune_id,new.adjoint_id,'Délégation effective',new.domaine,'deleg'); end if;
  end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.garde_demande()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text := (select private.my_role());
begin
  new.updated_at := now();
  if new.statut='traitee' and old.statut is distinct from 'traitee' and r is not null and r not in ('maire','adjoint','super_admin') then
    raise exception 'La validation finale est réservée au maire ou à l’adjoint'; end if;
  if new.service is distinct from old.service and r is not null and r not in ('maire','adjoint','cabinet','secretariat','super_admin') then
    raise exception 'L’orientation est réservée au secrétariat'; end if;
  if new.statut='pret_a_retirer' and old.statut is distinct from 'pret_a_retirer' then
    if old.statut not in ('acceptee','traitee') then
      raise exception 'Le document ne peut être déclaré prêt qu’après acceptation de la demande'; end if;
    if length(trim(coalesce(new.reponse,'')))=0 then
      raise exception 'Indiquez le lieu et les modalités de retrait avant de déclarer le document prêt'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.garde_instr()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                                                           declare r text := (select private.my_role());
                                                                                                                                                                                                                                                                           begin
                                                                                                                                                                                                                                                                             new.updated_at:=now();
                                                                                                                                                                                                                                                                               if r='adjoint' then
                                                                                                                                                                                                                                                                                   if (to_jsonb(new)-'{statut,reponse,pieces,updated_at}'::text[]) is distinct from (to_jsonb(old)-'{statut,reponse,pieces,updated_at}'::text[]) then raise exception 'Instruction : seuls le statut et la réponse sont modifiables'; end if;
                                                                                                                                                                                                                                                                                       if old.statut='cloturee' then raise exception 'Instruction clôturée'; end if;
                                                                                                                                                                                                                                                                                           if new.statut in ('nouvelle','cloturee') and new.statut is distinct from old.statut then raise exception 'Statut non autorisé pour un adjoint'; end if;
                                                                                                                                                                                                                                                                                             elsif r='secretariat' then
                                                                                                                                                                                                                                                                                                 if old.statut='cloturee' then raise exception 'Instruction clôturée'; end if;
                                                                                                                                                                                                                                                                                                     if new.statut='cloturee' then raise exception 'La clôture est réservée au maire'; end if;
                                                                                                                                                                                                                                                                                                       end if;
                                                                                                                                                                                                                                                                                                         if new.statut is distinct from old.statut and r='adjoint' then perform private.notifier_maires(new.commune_id,'Instruction mise à jour',new.reference||' : '||new.statut,'instr'); end if;
                                                                                                                                                                                                                                                                                                           if new.service is not null and new.service is distinct from old.service and new.service not in ('externe','adjoint') then perform private.notifier_role(new.commune_id,new.service,'Instruction affectée',new.reference||' : '||new.objet,'s_instr'); end if;
                                                                                                                                                                                                                                                                                                             return new; end $function$

CREATE OR REPLACE FUNCTION private.garde_rapport()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text := (select private.my_role());
begin
  new.updated_at:=now();
  if r='adjoint' then
    if new.observations_maire is distinct from old.observations_maire then raise exception 'Les observations du maire ne sont pas modifiables'; end if;
    if old.statut<>'brouillon' and ((to_jsonb(new)-'{statut,updated_at}'::text[]) is distinct from (to_jsonb(old)-'{statut,updated_at}'::text[]) or new.statut<>'archive') then raise exception 'Un rapport transmis n’est plus modifiable'; end if;
    if old.statut='brouillon' and new.statut not in ('brouillon','transmis') then raise exception 'Statut non autorisé'; end if;
  elsif r='maire' then
    if (to_jsonb(new)-'{statut,observations_maire,updated_at}'::text[]) is distinct from (to_jsonb(old)-'{statut,observations_maire,updated_at}'::text[]) then raise exception 'Le maire peut seulement annoter le rapport'; end if;
  end if;
  if new.statut='transmis' and old.statut='brouillon' then new.transmis_le:=now(); perform private.notifier_maires(new.commune_id,'Rapport transmis',new.titre,'rapp'); end if;
  if new.observations_maire is distinct from old.observations_maire and new.observations_maire is not null then perform private.notifier_adjoint(new.commune_id,new.adjoint_id,'Observations du maire',new.titre,'rapp'); end if;
  return new; end $function$

CREATE OR REPLACE FUNCTION private.notif_courrier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                         declare o public.courrier;
                                                                                                                                                         begin
                                                                                                                                                           if tg_op='UPDATE' then o:=old; end if;
                                                                                                                                                             if new.sens='in' then
                                                                                                                                                                 if tg_op='INSERT' and new.priorite='urgente' then perform private.notifier_maires(new.commune_id,'Courrier urgent',new.reference||' : '||new.objet,'s_cin'); end if;
                                                                                                                                                                     if new.service is not null and new.service not in ('maire','externe','secretariat','adjoint') and (tg_op='INSERT' or new.service is distinct from o.service) then perform private.notifier_role(new.commune_id,new.service,'Courrier affecté',new.reference||' : '||new.objet,'s_cin'); end if;
                                                                                                                                                                         if new.service='maire' and (tg_op='INSERT' or o.service is distinct from 'maire') then perform private.notifier_maires(new.commune_id,'Courrier transmis au maire',new.reference||' : '||new.objet,'s_cin'); end if;
                                                                                                                                                                             if new.adjoint_id is not null and (tg_op='INSERT' or new.adjoint_id is distinct from o.adjoint_id) then perform private.notifier_adjoint(new.commune_id,new.adjoint_id,'Courrier transmis',new.reference||' : '||new.objet,'s_cin'); end if;
                                                                                                                                                                               elsif tg_op='UPDATE' and new.statut is distinct from o.statut then
                                                                                                                                                                                   if new.statut='en_validation' then perform private.notifier_maires(new.commune_id,'Courrier à valider',new.reference||' : '||new.objet,'s_cout'); end if;
                                                                                                                                                                                       if new.statut='valide' then perform private.notifier_role(new.commune_id,'secretariat','Courrier validé',new.reference||' : '||new.objet,'s_cout'); end if;
                                                                                                                                                                                           if new.statut='signe' then perform private.notifier_role(new.commune_id,'secretariat','Courrier signé : à envoyer',new.reference||' : '||new.objet,'s_cout'); end if;
                                                                                                                                                                                             end if;
                                                                                                                                                                                               return null; end $function$

CREATE OR REPLACE FUNCTION private.paie_garde(p_roles text[], p_action text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid := private.my_commune(); r text := private.my_role();
begin
  if c is null or r is null or not private.hors_maintenance()
     or not (r = any (p_roles) or (r <> 'super_admin' and coalesce(public.org_droit('paie', p_action), false))) then
    raise exception 'Accès refusé' using errcode='42501'; end if;
  return c;
end $function$

CREATE OR REPLACE FUNCTION public._garde(p_commune text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not public.is_super_admin() then
   raise exception 'Accès refusé : super-administrateur actif et MFA AAL2 requis' using errcode='42501';
 end if;
 if private.is_platform_admin() then
   if not exists(select 1 from public.communes c where c.id::text=p_commune) then
     raise exception 'Commune introuvable' using errcode='42501';
   end if;
   return;
 end if;
 if p_commune is distinct from (
   select p.commune_id::text from public.profiles p where p.id=(select auth.uid()) and p.actif
 ) then
   raise exception 'Accès refusé : autre commune' using errcode='42501';
 end if;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_attribuer(p_email text, p_role text, p_slug text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  u uuid;
  c uuid;
BEGIN
  IF NOT private.is_platform_admin() THEN
    RAISE EXCEPTION 'Accès plateforme refusé : MFA AAL2 requise';
  END IF;

  IF p_role NOT IN (
    'maire','adjoint','cabinet','secretariat','finances',
    'rh','etat_civil','technique','agent','citoyen'
  ) THEN
    RAISE EXCEPTION 'Rôle invalide';
  END IF;

  SELECT id INTO u
  FROM auth.users
  WHERE lower(email) = lower(trim(p_email))
    AND NOT is_anonymous
  FOR UPDATE;

  IF u IS NULL THEN
    RAISE EXCEPTION 'Utilisateur introuvable : un compte nominatif doit d’abord être créé';
  END IF;

  PERFORM 1
  FROM public.platform_admins
  WHERE user_id=u
  FOR KEY SHARE;

  IF FOUND THEN
    RAISE EXCEPTION 'Un compte administrateur plateforme ne peut pas recevoir de rôle municipal';
  END IF;

  SELECT id INTO c
  FROM public.communes
  WHERE slug = lower(trim(p_slug));

  IF c IS NULL THEN
    RAISE EXCEPTION 'Commune inconnue';
  END IF;

  PERFORM 1
  FROM public.profiles
  WHERE id=u AND role::text='super_admin'
  FOR UPDATE;

  IF FOUND THEN
    RAISE EXCEPTION 'Un profil super_admin ne peut pas être modifié par cette opération';
  END IF;

  -- Un transfert intercommunal doit passer par une procédure dédiée
  -- qui met aussi à jour l'administrateur principal et l'audit des deux communes.
  PERFORM 1
  FROM public.profiles
  WHERE id=u AND commune_id IS NOT NULL AND commune_id <> c
  FOR UPDATE;

  IF FOUND THEN
    RAISE EXCEPTION 'Compte déjà affecté à une autre commune : transfert explicite requis';
  END IF;

  INSERT INTO public.profiles(id,role,commune_id)
  VALUES (u,p_role,c)
  ON CONFLICT (id)
  DO UPDATE SET role=EXCLUDED.role, commune_id=EXCLUDED.commune_id
  WHERE public.profiles.role::text <> 'super_admin'
    AND (public.profiles.commune_id IS NULL OR public.profiles.commune_id=c);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Attribution du rôle impossible';
  END IF;
END
$function$

CREATE OR REPLACE FUNCTION public.completer_demande(p_commune text, p_numero text, p_pieces text[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c record; d record;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF p_pieces IS NULL OR cardinality(p_pieces)<1 OR cardinality(p_pieces)>3 THEN
    RETURN false;
  END IF;

  IF (SELECT count(DISTINCT x) FROM unnest(p_pieces) AS u(x))<>cardinality(p_pieces) THEN
    RETURN false;
  END IF;

  SELECT id INTO c
  FROM public.communes
  WHERE slug=p_commune AND statut IN ('essai','actif');

  IF c.id IS NULL THEN
    RETURN false;
  END IF;

  SELECT id,pieces INTO d
  FROM public.demandes
  WHERE commune_id=c.id
    AND numero=upper(trim(p_numero))
    AND statut='en_attente_pieces'
    AND (
      upper(trim(p_numero)) ~ '^[A-Z0-9]{3}-[0-9]{4}-[0-9A-F]{32}$'
      OR citoyen_id=auth.uid()
    )
  FOR UPDATE;

  IF d.id IS NULL
     OR cardinality(coalesce(d.pieces,'{}'::text[]))+cardinality(p_pieces)>12
     OR coalesce(d.pieces,'{}'::text[]) && p_pieces THEN
    RETURN false;
  END IF;

  IF EXISTS(
    SELECT 1
    FROM unnest(p_pieces) AS f(path)
    WHERE f.path IS NULL
      OR f.path !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(pdf|jpg|png|webp)$'
      OR split_part(f.path,'/',1)<>c.id::text
      OR NOT EXISTS(
        SELECT 1
        FROM storage.objects o
        WHERE o.bucket_id='pieces'
          AND o.name=f.path
          AND o.owner_id=auth.uid()::text
      )
  ) THEN
    RETURN false;
  END IF;

  UPDATE public.demandes
  SET pieces=coalesce(pieces,'{}'::text[])||p_pieces,
      statut='en_cours'
  WHERE id=d.id;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.convoquer_reunion(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  r public.reunions;
BEGIN
  IF auth.uid() IS NULL
     OR NOT (
       private.is_platform_admin()
       OR coalesce(private.my_role() IN ('maire','secretariat','super_admin'), false)
     ) THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  SELECT * INTO r
  FROM public.reunions
  WHERE id = p_id;

  IF r.id IS NULL
     OR (
       r.commune_id IS DISTINCT FROM private.my_commune()
       AND NOT private.is_platform_admin()
     ) THEN
    RAISE EXCEPTION 'Réunion introuvable';
  END IF;

  UPDATE public.reunions
  SET convoquee = true
  WHERE id = p_id;

  INSERT INTO public.notifications(commune_id,user_id,titre,corps,lien)
  SELECT r.commune_id,a.user_id,'Convocation',
         r.objet || ' — ' || to_char(r.jour,'DD/MM/YYYY') || ' ' || to_char(r.heure,'HH24:MI'),
         'reun'
  FROM public.reunion_participants p
  JOIN public.adjoints a ON a.id = p.adjoint_id
  WHERE p.reunion_id = p_id
    AND a.user_id IS NOT NULL;

  PERFORM private.notifier_maires(r.commune_id,'Réunion convoquée',r.objet,'reun');
END;
$function$

CREATE OR REPLACE FUNCTION public.creer_demande(p_commune text, p_type text, p_nom text, p_message text, p_objet text DEFAULT NULL::text, p_contact text DEFAULT NULL::text, p_pieces text[] DEFAULT '{}'::text[], p_demarche uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.communes; n text; sv text; dm public.demarches; v_pieces text[]:=coalesce(p_pieces,'{}'::text[]);
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Session citoyenne requise'; END IF;
 IF char_length(trim(coalesce(p_nom,''))) NOT BETWEEN 1 AND 120 OR char_length(trim(coalesce(p_message,''))) NOT BETWEEN 1 AND 2000 OR char_length(coalesce(p_objet,''))>200 OR char_length(coalesce(p_contact,''))>40 OR cardinality(v_pieces)>3 THEN RAISE EXCEPTION 'Demande invalide'; END IF;
 IF (SELECT count(DISTINCT x) FROM unnest(v_pieces) AS u(x))<>cardinality(v_pieces) THEN RAISE EXCEPTION 'Pièces invalides'; END IF;
 UPDATE public.communes SET compteur=compteur+1 WHERE slug=p_commune AND statut IN ('essai','actif') RETURNING * INTO c;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Commune inconnue'; END IF;
 IF p_demarche IS NOT NULL THEN SELECT * INTO dm FROM public.demarches WHERE id=p_demarche AND commune_id=c.id AND statut='actif'; IF dm.id IS NULL THEN RAISE EXCEPTION 'Démarche invalide'; END IF; p_type:=dm.type; END IF;
 IF p_type NOT IN ('État civil','Audience','Aide sociale','Travaux publics','Urbanisme','Environnement','Éducation','Sport et culture','Commerce','Agriculture et pêche','Réclamations','Associations') THEN RAISE EXCEPTION 'Demande invalide'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(v_pieces) AS f(path) WHERE f.path IS NULL OR f.path !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(pdf|jpg|png|webp)$' OR split_part(f.path,'/',1)<>c.id::text OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='pieces' AND o.name=f.path AND o.owner_id=auth.uid()::text)) THEN RAISE EXCEPTION 'Pièce invalide ou inaccessible'; END IF;
 sv:=coalesce(dm.service,CASE p_type WHEN 'État civil' THEN 'etat_civil' WHEN 'Travaux publics' THEN 'technique' WHEN 'Urbanisme' THEN 'technique' WHEN 'Environnement' THEN 'technique' ELSE 'secretariat' END);
 n:=upper(left(c.slug,3))||'-'||lpad(c.compteur::text,4,'0')||'-'||upper(replace(gen_random_uuid()::text,'-',''));
 INSERT INTO public.demandes(commune_id,numero,type,nom,message,objet,contact,pieces,service,citoyen_id) VALUES(c.id,n,p_type,trim(p_nom),trim(p_message),nullif(trim(coalesce(p_objet,'')),''),nullif(trim(coalesce(p_contact,'')),''),v_pieces,sv,auth.uid());
 RETURN n;
END;$function$

CREATE OR REPLACE FUNCTION public.creer_rdv(p_commune text, p_service text, p_nom text, p_contact text, p_motif text, p_date date, p_heure time without time zone DEFAULT NULL::time without time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c record;n text;u uuid:=auth.uid();pl boolean;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'session'; END IF;
 SELECT id INTO c FROM public.communes WHERE slug=p_commune AND statut IN ('essai','actif');
 IF c.id IS NULL THEN RAISE EXCEPTION 'commune'; END IF;
 IF p_date IS NULL OR p_date<=current_date OR p_date>current_date+90 THEN RAISE EXCEPTION 'date'; END IF;
 IF (SELECT count(*) FROM public.rdv_demandes WHERE citoyen_id=u AND statut='demandee')>=3 THEN RAISE EXCEPTION 'limite'; END IF;
 SELECT EXISTS(SELECT 1 FROM public.rdv_planning WHERE commune_id=c.id AND actif) INTO pl;
 IF pl THEN
  IF p_heure IS NULL OR NOT EXISTS(SELECT 1 FROM public.rdv_slots(c.id,p_date) s WHERE s.heure=p_heure) THEN RAISE EXCEPTION 'creneau'; END IF;
  IF EXISTS(SELECT 1 FROM public.rdv_demandes r WHERE r.commune_id=c.id AND r.service=p_service AND r.statut='confirmee' AND r.date_confirmee=p_date AND r.heure_confirmee=p_heure) THEN RAISE EXCEPTION 'creneau'; END IF;
 END IF;
 n:='RDV-'||upper(replace(gen_random_uuid()::text,'-',''));
 INSERT INTO public.rdv_demandes(commune_id,citoyen_id,numero,service,nom,contact,motif,date_souhaitee,heure_souhaitee) VALUES(c.id,u,n,p_service,trim(p_nom),nullif(trim(coalesce(p_contact,'')),''),trim(p_motif),p_date,case when pl then p_heure end);
 RETURN n;
END;$function$

CREATE OR REPLACE FUNCTION public.lier_adjoint(p_adjoint uuid, p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid; a public.adjoints;
BEGIN
  IF NOT (
    private.is_platform_admin()
    OR private.my_role() IN ('maire','super_admin')
  ) THEN RAISE EXCEPTION 'Accès refusé'; END IF;

  SELECT * INTO a FROM public.adjoints WHERE id = p_adjoint;
  IF a.id IS NULL OR (
    NOT private.is_platform_admin()
    AND a.commune_id IS DISTINCT FROM private.my_commune()
  ) THEN RAISE EXCEPTION 'Adjoint introuvable'; END IF;

  SELECT id INTO u FROM auth.users
  WHERE lower(email) = lower(trim(p_email));
  IF u IS NULL THEN
    RAISE EXCEPTION 'Aucun compte avec cet e-mail : l’administrateur doit d’abord le créer';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = u AND commune_id IS DISTINCT FROM a.commune_id
  ) THEN RAISE EXCEPTION 'Ce compte appartient à une autre commune'; END IF;

  IF EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = u AND role IN ('maire','super_admin')
  ) THEN RAISE EXCEPTION 'Ce compte a un autre rôle'; END IF;

  INSERT INTO public.profiles(id,role,commune_id)
  VALUES (u,'adjoint',a.commune_id)
  ON CONFLICT (id)
  DO UPDATE SET role = 'adjoint', commune_id = EXCLUDED.commune_id;

  UPDATE public.adjoints SET user_id = u WHERE id = p_adjoint;
END
$function$

CREATE OR REPLACE FUNCTION public.org_aa_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE pc uuid;
BEGIN
  IF NEW.personnel_id IS NOT NULL THEN
    SELECT commune_id INTO pc FROM public.personnel WHERE id=NEW.personnel_id;
  ELSE
    SELECT commune_id INTO pc FROM public.adjoints WHERE id=NEW.adjoint_id;
  END IF;

  IF pc IS DISTINCT FROM NEW.commune_id THEN
    RAISE EXCEPTION 'Personne d''une autre commune';
  END IF;

  IF NEW.service_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.services
       WHERE id=NEW.service_id AND commune_id=NEW.commune_id
     ) THEN
    RAISE EXCEPTION 'Service d''une autre commune';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.org_agent_affectations o
    WHERE o.id IS DISTINCT FROM NEW.id
      AND o.commune_id=NEW.commune_id
      AND o.poste_code=NEW.poste_code
      AND o.personnel_id IS NOT DISTINCT FROM NEW.personnel_id
      AND o.adjoint_id IS NOT DISTINCT FROM NEW.adjoint_id
      AND daterange(o.debut,coalesce(o.fin,'infinity'::date),'[]')
          && daterange(NEW.debut,coalesce(NEW.fin,'infinity'::date),'[]')
  ) THEN
    RAISE EXCEPTION 'Affectation contradictoire : cette personne occupe déjà ce poste sur la période';
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.org_affectation_fin(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c uuid:=public.org_commune();
BEGIN
  IF NOT public.org_droit('org','administrer') THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  UPDATE public.org_affectations
  SET actif=false,fin=least(coalesce(fin,current_date),current_date)
  WHERE id=p_id AND commune_id=c;

  IF NOT FOUND THEN RAISE EXCEPTION 'Affectation introuvable'; END IF;
  PERFORM public.org_log(c,'org_affectation_fin',p_id::text,NULL);
END
$function$

CREATE OR REPLACE FUNCTION public.org_affecter(p_user uuid, p_poste text, p_service text DEFAULT NULL::text, p_debut date DEFAULT NULL::date, p_fin date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid:=public.org_commune();
  did uuid;
  d date:=coalesce(p_debut,current_date);
  role_cible text;
BEGIN
  IF NOT public.org_droit('org','administrer') THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  PERFORM 1 FROM public.profiles
  WHERE id=p_user AND commune_id=c AND role::text<>'super_admin'
  FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Utilisateur invalide'; END IF;

  SELECT role_code INTO role_cible
  FROM public.org_postes
  WHERE commune_id=c AND code=p_poste AND actif;
  IF NOT FOUND THEN RAISE EXCEPTION 'Poste invalide'; END IF;

  IF p_service IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.services WHERE commune_id=c AND code=p_service
  ) THEN
    RAISE EXCEPTION 'Service invalide';
  END IF;

  IF NOT public.org_peut_accorder(role_cible) THEN
    RAISE EXCEPTION 'Vous ne pouvez affecter qu''à un poste dont les droits vous appartiennent';
  END IF;

  IF p_fin IS NOT NULL AND p_fin<d THEN
    RAISE EXCEPTION 'Période invalide';
  END IF;

  INSERT INTO public.org_affectations(
    commune_id,user_id,poste_code,service_code,debut,fin,created_by
  )
  VALUES(c,p_user,p_poste,p_service,d,p_fin,(SELECT auth.uid()))
  RETURNING id INTO did;

  PERFORM public.org_log(
    c,'org_affecter',p_user::text,
    jsonb_build_object('poste',p_poste,'debut',d,'fin',p_fin)
  );
  RETURN did;
END
$function$

CREATE OR REPLACE FUNCTION public.org_deleguer(p_a uuid, p_module text, p_action text, p_debut timestamp with time zone, p_fin timestamp with time zone, p_motif text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid:=public.org_commune();
  u uuid:=(SELECT auth.uid());
  t record;
  did uuid;
  d timestamptz:=coalesce(p_debut,now());
BEGIN
  IF c IS NULL OR u IS NULL THEN RAISE EXCEPTION 'Accès refusé'; END IF;

  IF p_action NOT IN (
    'consulter','creer','modifier','supprimer','valider','rejeter',
    'signer','exporter','imprimer','partager','administrer'
  ) THEN
    RAISE EXCEPTION 'Action inconnue';
  END IF;

  SELECT role,commune_id INTO t
  FROM public.profiles
  WHERE id=p_a AND coalesce(actif,true)
  FOR KEY SHARE;

  IF NOT FOUND OR t.commune_id IS DISTINCT FROM c
     OR t.role IN ('super_admin','citoyen') THEN
    RAISE EXCEPTION 'Bénéficiaire invalide';
  END IF;

  IF p_a=u THEN RAISE EXCEPTION 'Délégation à soi-même impossible'; END IF;
  IF p_fin IS NULL OR p_fin<=d OR p_fin>d+interval '1 year' THEN
    RAISE EXCEPTION 'Période invalide (1 an maximum)';
  END IF;
  IF NOT public.org_droit_propre(u,p_module,p_action) THEN
    RAISE EXCEPTION 'Vous ne pouvez déléguer que les droits que vous détenez';
  END IF;

  INSERT INTO public.org_delegations_droits(
    commune_id,de_user,a_user,module,action,debut,fin,motif
  )
  VALUES(c,u,p_a,p_module,p_action,d,p_fin,p_motif)
  RETURNING id INTO did;

  PERFORM public.org_log(
    c,'org_deleguer',p_a::text,
    jsonb_build_object('module',p_module,'action',p_action,'debut',d,'fin',p_fin)
  );
  RETURN did;
END
$function$

CREATE OR REPLACE FUNCTION public.org_droit_propre(u uuid, m text, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p record; o boolean;
begin
 select role,commune_id into p
 from public.profiles
 where id=u and coalesce(actif,true);
 if not found then return false; end if;
 if u=(select auth.uid()) and private.is_platform_admin() then return true; end if;
 if p.role='maire' then return true; end if;
 if p.role='super_admin' then
   return u=(select auth.uid()) and public.is_super_admin();
 end if;
 if a='consulter' then
   select autorise into o
   from public.permissions_utilisateurs
   where commune_id=p.commune_id::text and user_id=u and cle=m;
   if found then return o; end if;
 end if;
 return exists(
   select 1 from public.org_affectations f
   join public.org_postes po on po.commune_id=f.commune_id and po.code=f.poste_code and po.actif
   join public.org_roles r on r.commune_id=po.commune_id and r.code=po.role_code and r.actif
   join public.org_role_droits d on d.commune_id=r.commune_id and d.role_code=r.code
   where f.user_id=u and f.commune_id=p.commune_id and f.actif
     and f.debut<=current_date and (f.fin is null or f.fin>=current_date)
     and d.module=m and d.action=a
 );
end
$function$

CREATE OR REPLACE FUNCTION public.org_gest(p_slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid;
begin
  select id into c from public.communes where slug=p_slug;
  if c is null then raise exception 'Commune introuvable'; end if;
  if auth.uid() is null or not coalesce(
    private.is_platform_admin() or public.is_super_admin()
    or (private.my_role()='maire' and private.my_commune()=c),false
  ) then raise exception 'Accès refusé'; end if;
  return c;
end
$function$

CREATE OR REPLACE FUNCTION public.org_init()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c uuid;
BEGIN
  IF NOT public.org_droit('org','administrer') THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;
  c:=public.org_commune();
  PERFORM public.org_seed(c);
  PERFORM public.org_log(c,'org_init',NULL,NULL);
END
$function$

CREATE OR REPLACE FUNCTION public.org_poste_save(p_code text, p_nom text, p_famille text, p_role text, p_parent text, p_service text, p_actif boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid:=public.org_commune();
  x text:=p_parent;
  n integer:=0;
BEGIN
  IF NOT public.org_droit('org','administrer') THEN RAISE EXCEPTION 'Accès refusé'; END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.org_roles WHERE commune_id=c AND code=p_role AND actif
  ) THEN RAISE EXCEPTION 'Rôle invalide'; END IF;
  IF NOT public.org_peut_accorder(p_role) THEN
    RAISE EXCEPTION 'Vous ne pouvez utiliser qu''un rôle dont les droits vous appartiennent';
  END IF;
  IF p_parent IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.org_postes WHERE commune_id=c AND code=p_parent
  ) THEN RAISE EXCEPTION 'Poste supérieur introuvable'; END IF;

  WHILE x IS NOT NULL AND n<30 LOOP
    IF x=p_code THEN RAISE EXCEPTION 'Lien hiérarchique circulaire'; END IF;
    SELECT parent_code INTO x
    FROM public.org_postes WHERE commune_id=c AND code=x;
    n:=n+1;
  END LOOP;

  INSERT INTO public.org_postes(
    commune_id,code,nom,famille,role_code,parent_code,service_code,actif
  )
  VALUES(c,p_code,trim(p_nom),p_famille,p_role,p_parent,p_service,coalesce(p_actif,true))
  ON CONFLICT(commune_id,code) DO UPDATE
  SET nom=excluded.nom,famille=excluded.famille,role_code=excluded.role_code,
      parent_code=excluded.parent_code,service_code=excluded.service_code,
      actif=excluded.actif;

  PERFORM public.org_log(
    c,'org_poste_save',p_code,
    jsonb_build_object('role',p_role,'parent',p_parent,'actif',p_actif)
  );
END
$function$

CREATE OR REPLACE FUNCTION public.org_revoquer(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid:=public.org_commune();
  u uuid:=(SELECT auth.uid());
  n integer;
BEGIN
  UPDATE public.org_delegations_droits
  SET revoque_le=now(),revoque_par=u
  WHERE id=p_id AND commune_id=c AND revoque_le IS NULL
    AND (de_user=u OR public.org_droit('org','administrer'));

  GET DIAGNOSTICS n=ROW_COUNT;
  IF n=0 THEN RAISE EXCEPTION 'Délégation introuvable ou accès refusé'; END IF;
  PERFORM public.org_log(c,'org_revoquer',p_id::text,NULL);
END
$function$

CREATE OR REPLACE FUNCTION public.org_role_droit_set(p_role text, p_module text, p_action text, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c uuid:=public.org_commune(); u uuid:=(SELECT auth.uid());
BEGIN
  IF NOT public.org_droit('org','administrer') THEN RAISE EXCEPTION 'Accès refusé'; END IF;
  IF p_role='maire' OR NOT EXISTS(
    SELECT 1 FROM public.org_roles WHERE commune_id=c AND code=p_role
  ) THEN RAISE EXCEPTION 'Rôle invalide'; END IF;

  IF p_on THEN
    IF NOT public.org_droit_propre(u,p_module,p_action) THEN
      RAISE EXCEPTION 'Vous ne pouvez accorder que les droits que vous détenez';
    END IF;
    INSERT INTO public.org_role_droits(commune_id,role_code,module,action)
    VALUES(c,p_role,p_module,p_action)
    ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM public.org_role_droits
    WHERE commune_id=c AND role_code=p_role AND module=p_module AND action=p_action;
  END IF;

  PERFORM public.org_log(
    c,'org_role_droit',p_role,
    jsonb_build_object('module',p_module,'action',p_action,'accorde',p_on)
  );
END
$function$

CREATE OR REPLACE FUNCTION public.org_role_save(p_code text, p_nom text, p_desc text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c uuid:=public.org_commune();
BEGIN
  IF NOT public.org_droit('org','administrer') THEN RAISE EXCEPTION 'Accès refusé'; END IF;
  IF p_code='maire' THEN RAISE EXCEPTION 'Rôle protégé'; END IF;
  IF coalesce(trim(p_nom),'')='' THEN RAISE EXCEPTION 'Nom obligatoire'; END IF;

  INSERT INTO public.org_roles(commune_id,code,nom,description)
  VALUES(c,p_code,trim(p_nom),p_desc)
  ON CONFLICT(commune_id,code) DO UPDATE
  SET nom=excluded.nom,description=excluded.description;

  PERFORM public.org_log(c,'org_role_save',p_code,jsonb_build_object('nom',p_nom));
END
$function$

CREATE OR REPLACE FUNCTION public.org_sa_affectation_fin(p_commune text, p_id uuid, p_fin date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid:=public.org_gest(p_commune); a record; linked_user uuid; ending date:=coalesce(p_fin,current_date);
begin
 select * into a from public.org_agent_affectations where id=p_id and commune_id=c for update;
 if not found then raise exception 'Affectation introuvable'; end if;
 if ending<a.debut then raise exception 'La date de fin précède la date de début'; end if;
 if a.personnel_id is not null then select user_id into linked_user from public.personnel where id=a.personnel_id and commune_id=c; end if;
 if a.adjoint_id is not null then select user_id into linked_user from public.adjoints where id=a.adjoint_id and commune_id=c; end if;
 update public.org_agent_affectations set fin=ending where id=p_id and commune_id=c;
 if linked_user is not null then
  update public.org_affectations set fin=ending,actif=(ending>=current_date)
  where commune_id=c and user_id=linked_user and poste_code=a.poste_code and debut=a.debut;
 end if;
 perform public.org_log(c,'org_agent_affectation_fin',p_id::text,NULL);
end
$function$

CREATE OR REPLACE FUNCTION public.org_sa_affecter(p_commune text, p_personnel uuid, p_adjoint uuid, p_poste text, p_service text, p_debut date, p_fin date, p_motif text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid:=public.org_gest(p_commune); sid uuid; r uuid; linked_user uuid; start_date date:=coalesce(p_debut,current_date);
begin
 if (p_personnel is null)=(p_adjoint is null) then raise exception 'Indiquez une personne du personnel ou un adjoint'; end if;
 if p_fin is not null and p_fin<start_date then raise exception 'La date de fin précède la date de début'; end if;
 if p_personnel is not null then select user_id into linked_user from public.personnel where id=p_personnel and commune_id=c and actif for key share; if not found then raise exception 'Personnel introuvable ou inactif dans cette commune'; end if; end if;
 if p_adjoint is not null then select user_id into linked_user from public.adjoints where id=p_adjoint and commune_id=c and actif for key share; if not found then raise exception 'Adjoint introuvable ou inactif dans cette commune'; end if; end if;
 perform 1 from public.org_postes where commune_id=c and code=p_poste and actif for key share;
 if not found then raise exception 'Poste introuvable ou inactif'; end if;
 if p_service is not null then select id into sid from public.services where commune_id=c and code=p_service and actif for key share; if sid is null then raise exception 'Service introuvable ou inactif'; end if; end if;
 if exists(
  select 1 from public.org_agent_affectations a
  where a.commune_id=c and a.poste_code=p_poste
   and ((p_personnel is not null and a.personnel_id=p_personnel) or (p_adjoint is not null and a.adjoint_id=p_adjoint))
   and daterange(a.debut,coalesce(a.fin,'infinity'::date),'[]') && daterange(start_date,coalesce(p_fin,'infinity'::date),'[]')
 ) then raise exception 'Cette personne occupe déjà ce poste sur une période qui se chevauche'; end if;
 insert into public.org_agent_affectations(commune_id,personnel_id,adjoint_id,poste_code,service_id,debut,fin,motif)
 values(c,p_personnel,p_adjoint,p_poste,sid,start_date,p_fin,p_motif) returning id into r;
 if linked_user is not null and exists(select 1 from public.profiles where id=linked_user and coalesce(actif,true)) then
  update public.org_affectations set service_code=p_service,fin=p_fin,actif=(p_fin is null or p_fin>=current_date)
  where commune_id=c and user_id=linked_user and poste_code=p_poste and debut=start_date;
  if not found then insert into public.org_affectations(commune_id,user_id,poste_code,service_code,debut,fin,actif,created_by)
   values(c,linked_user,p_poste,p_service,start_date,p_fin,(p_fin is null or p_fin>=current_date),auth.uid()); end if;
 end if;
 perform public.org_log(c,'org_agent_affecter',p_poste,jsonb_build_object('id',r));
 return r;
end
$function$

CREATE OR REPLACE FUNCTION public.org_sa_agent_save(p_commune text, p_id uuid, p_prenom text, p_nom text, p_fonction text, p_service text, p_contrat text, p_tel text, p_email text, p_matricule text, p_obs text, p_actif boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid:=public.org_gest(p_commune); sid uuid; sn text; r uuid; linked_user uuid; linked_role text;
begin
  if length(trim(coalesce(p_prenom,'')))<1 or length(trim(coalesce(p_nom,'')))<1 then raise exception 'Prénom et nom obligatoires'; end if;
  if p_service is not null then select id,nom into sid,sn from public.services where commune_id=c and code=p_service and actif; if sid is null then raise exception 'Service introuvable ou inactif'; end if; end if;
  if p_id is null then
    insert into public.personnel(commune_id,prenom,nom,fonction,service,service_id,type_contrat,telephone,email,matricule,observations,actif)
    values(c,trim(p_prenom),trim(p_nom),p_fonction,sn,sid,coalesce(p_contrat,'Permanent'),p_tel,p_email,p_matricule,p_obs,coalesce(p_actif,true)) returning id into r;
  else
    update public.personnel set prenom=trim(p_prenom),nom=trim(p_nom),fonction=p_fonction,service=sn,service_id=sid,
      type_contrat=coalesce(p_contrat,type_contrat),telephone=p_tel,email=p_email,matricule=p_matricule,observations=p_obs,
      actif=coalesce(p_actif,actif),date_sortie=case when p_actif is false then coalesce(date_sortie,current_date) when p_actif is true then null else date_sortie end
    where id=p_id and commune_id=c returning id,user_id into r,linked_user;
    if r is null then raise exception 'Fiche introuvable'; end if;
  end if;
  if p_actif is false then
    if linked_user is not null then
      select role::text into linked_role from public.profiles where id=linked_user;
      if linked_role in ('maire','adjoint','super_admin') or exists(select 1 from public.platform_admins where user_id=linked_user and actif) then
        raise exception 'Ce compte exerce une fonction protégée ; procédez à son remplacement selon la procédure de la commune';
      end if;
    end if;
    update public.org_agent_affectations set fin=current_date where commune_id=c and personnel_id=r and debut<=current_date and (fin is null or fin>=current_date);
    if linked_user is not null then
      update public.org_affectations oa set fin=case when oa.debut<=current_date then current_date else oa.fin end,actif=false
      where oa.commune_id=c and oa.user_id=linked_user and oa.actif
        and exists(select 1 from public.org_agent_affectations a where a.commune_id=c and a.personnel_id=r and a.poste_code=oa.poste_code and a.debut=oa.debut);
      update public.profiles set actif=false where id=linked_user;
    end if;
  end if;
  perform public.org_log(c,'org_agent_save',r::text,jsonb_build_object('actif',p_actif));
  return r;
end
$function$

CREATE OR REPLACE FUNCTION public.org_sa_fusionner(p_commune text, p_garde uuid, p_absorbe uuid, p_confirme boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid := public.org_gest(p_commune);
  garde_user uuid;
  absorbe_user uuid;
  n integer;
BEGIN
  IF p_confirme IS NOT TRUE THEN
    RAISE EXCEPTION 'Fusion non confirmée : vérifiez que les deux fiches sont la même personne';
  END IF;

  IF p_garde=p_absorbe THEN
    RAISE EXCEPTION 'Fiches identiques';
  END IF;

  -- Verrouille les deux fiches dans un ordre stable pour éviter les courses concurrentes.
  PERFORM 1
  FROM public.personnel
  WHERE id IN (p_garde,p_absorbe) AND commune_id=c
  ORDER BY id
  FOR UPDATE;

  SELECT count(*) INTO n
  FROM public.personnel
  WHERE id IN (p_garde,p_absorbe)
    AND commune_id=c
    AND fusionne_dans IS NULL;

  IF n<>2 THEN
    RAISE EXCEPTION 'Fiches introuvables ou déjà fusionnées';
  END IF;

  SELECT user_id INTO garde_user
  FROM public.personnel WHERE id=p_garde AND commune_id=c;

  SELECT user_id INTO absorbe_user
  FROM public.personnel WHERE id=p_absorbe AND commune_id=c;

  IF garde_user IS NOT NULL AND absorbe_user IS NOT NULL
     AND garde_user<>absorbe_user THEN
    RAISE EXCEPTION 'Les deux fiches sont liées à des comptes différents : arbitrage manuel requis';
  END IF;

  IF EXISTS (SELECT 1 FROM public.remunerations WHERE personnel_id=p_absorbe)
     OR EXISTS (SELECT 1 FROM public.conges WHERE personnel_id=p_absorbe)
     OR EXISTS (SELECT 1 FROM public.conges_droits WHERE personnel_id=p_absorbe)
     OR EXISTS (SELECT 1 FROM public.paie_lignes WHERE personnel_id=p_absorbe) THEN
    RAISE EXCEPTION 'La fiche à absorber a des données RH (paie, congés, rémunération) : fusion manuelle requise';
  END IF;

  UPDATE public.personnel
  SET user_id=NULL
  WHERE id=p_absorbe AND commune_id=c;

  UPDATE public.personnel
  SET user_id=coalesce(user_id,absorbe_user)
  WHERE id=p_garde AND commune_id=c;

  UPDATE public.org_agent_affectations
  SET personnel_id=p_garde
  WHERE personnel_id=p_absorbe AND commune_id=c;

  UPDATE public.personnel
  SET actif=false,
      date_sortie=coalesce(date_sortie,current_date),
      fusionne_dans=p_garde
  WHERE id=p_absorbe AND commune_id=c;

  PERFORM public.org_log(c,'org_agent_fusion',p_absorbe::text,
    jsonb_build_object('vers',p_garde));
END
$function$

CREATE OR REPLACE FUNCTION public.org_sa_lier_adjoint_compte(p_commune text, p_adjoint uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 c uuid:=public.org_gest(p_commune); old_user uuid; adjoint_active boolean;
 profile_commune uuid; profile_role text; profile_active boolean; invite_pending boolean; linked_adjoint uuid;
begin
 select user_id,actif into old_user,adjoint_active from public.adjoints where id=p_adjoint and commune_id=c for update;
 if not found then raise exception 'Adjoint introuvable dans cette commune'; end if;
 if p_user is not null then
  if not adjoint_active then raise exception 'Un adjoint inactif ne peut pas recevoir de compte'; end if;
  select p.commune_id,p.role::text,p.actif,coalesce(u.raw_user_meta_data->>'invite_pending','false')='true'
   into profile_commune,profile_role,profile_active,invite_pending
  from public.profiles p join auth.users u on u.id=p.id where p.id=p_user for key share of p;
  if not found or profile_commune is distinct from c or profile_role<>'adjoint'
     or (not coalesce(profile_active,false) and not invite_pending) then
    raise exception 'Le compte doit être un compte adjoint de cette commune, actif ou en attente d’invitation';
  end if;
  if exists(select 1 from public.platform_admins where user_id=p_user) then raise exception 'Compte plateforme interdit'; end if;
  if exists(select 1 from public.personnel where user_id=p_user) then raise exception 'Compte déjà lié à une fiche du personnel'; end if;
  select id into linked_adjoint from public.adjoints where user_id=p_user and id<>p_adjoint for update;
  if found then raise exception 'Ce compte est déjà lié à un autre adjoint'; end if;
 end if;
 update public.adjoints set user_id=p_user where id=p_adjoint and commune_id=c;
 if old_user is not null and old_user is distinct from p_user then
  update public.org_affectations oa set fin=case when oa.debut<=current_date then current_date else oa.fin end,actif=false
  where oa.commune_id=c and oa.user_id=old_user and oa.actif
   and exists(select 1 from public.org_agent_affectations a where a.commune_id=c and a.adjoint_id=p_adjoint and a.poste_code=oa.poste_code and a.debut=oa.debut);
 end if;
 if p_user is not null then
  update public.org_affectations oa set service_code=(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),fin=a.fin,actif=(a.fin is null or a.fin>=current_date)
  from public.org_agent_affectations a where oa.commune_id=c and oa.user_id=p_user and a.commune_id=c and a.adjoint_id=p_adjoint and oa.poste_code=a.poste_code and oa.debut=a.debut;
  insert into public.org_affectations(commune_id,user_id,poste_code,service_code,debut,fin,actif,created_by)
  select c,p_user,a.poste_code,(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),a.debut,a.fin,(a.fin is null or a.fin>=current_date),auth.uid()
  from public.org_agent_affectations a where a.commune_id=c and a.adjoint_id=p_adjoint
   and not exists(select 1 from public.org_affectations oa where oa.commune_id=c and oa.user_id=p_user and oa.poste_code=a.poste_code and oa.debut=a.debut);
 end if;
 perform public.org_log(c,'org_adjoint_lien_compte',p_adjoint::text,jsonb_build_object('user',p_user,'invite_inactif_accepte',p_user is not null and not coalesce(profile_active,false)));
end
$function$

