  where oa.commune_id=c and oa.user_id=old_user and oa.actif
    and exists(select 1 from public.org_agent_affectations a where a.commune_id=c and a.personnel_id=p_personnel and a.poste_code=oa.poste_code and a.debut=oa.debut);
 end if;
 if p_user is not null then
  update public.org_affectations oa set service_code=(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),fin=a.fin,actif=(a.fin is null or a.fin>=current_date)
  from public.org_agent_affectations a where oa.commune_id=c and oa.user_id=p_user and a.commune_id=c and a.personnel_id=p_personnel and oa.poste_code=a.poste_code and oa.debut=a.debut;
  insert into public.org_affectations(commune_id,user_id,poste_code,service_code,debut,fin,actif,created_by)
  select c,p_user,a.poste_code,(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),a.debut,a.fin,(a.fin is null or a.fin>=current_date),auth.uid()
  from public.org_agent_affectations a where a.commune_id=c and a.personnel_id=p_personnel
   and not exists(select 1 from public.org_affectations oa where oa.commune_id=c and oa.user_id=p_user and oa.poste_code=a.poste_code and oa.debut=a.debut);
 end if;
 perform public.org_log(c,'org_agent_lien_compte',p_personnel::text,jsonb_build_object('user',p_user,'invite_inactif_accepte',p_user is not null and not coalesce(profile_active,false)));
end
$function$

CREATE OR REPLACE FUNCTION public.org_sa_poste_save(p_commune text, p_code text, p_nom text, p_famille text, p_role text, p_parent text, p_service text, p_actif boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid:=public.org_gest(p_commune);
  x text:=p_parent;
  n integer:=0;
BEGIN
  IF p_code IS NULL OR p_code !~ '^[a-z][a-z0-9_]{1,40}$' THEN
    RAISE EXCEPTION 'Code de poste invalide';
  END IF;
  IF length(trim(coalesce(p_nom,'')))<2 THEN
    RAISE EXCEPTION 'Intitulé obligatoire';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.org_roles
    WHERE commune_id=c AND code=p_role AND actif
  ) THEN
    RAISE EXCEPTION 'Rôle invalide';
  END IF;
  IF p_parent IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.org_postes WHERE commune_id=c AND code=p_parent
  ) THEN
    RAISE EXCEPTION 'Poste supérieur introuvable';
  END IF;
  IF p_service IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.services WHERE commune_id=c AND code=p_service
  ) THEN
    RAISE EXCEPTION 'Service introuvable';
  END IF;

  WHILE x IS NOT NULL AND n<30 LOOP
    IF x=p_code THEN RAISE EXCEPTION 'Lien hiérarchique circulaire'; END IF;
    SELECT parent_code INTO x
    FROM public.org_postes WHERE commune_id=c AND code=x;
    n:=n+1;
  END LOOP;

  INSERT INTO public.org_postes(
    commune_id,code,nom,famille,role_code,parent_code,service_code,actif
  )
  VALUES (
    c,p_code,trim(p_nom),p_famille,p_role,p_parent,p_service,coalesce(p_actif,true)
  )
  ON CONFLICT(commune_id,code) DO UPDATE
  SET nom=excluded.nom,famille=excluded.famille,role_code=excluded.role_code,
      parent_code=excluded.parent_code,service_code=excluded.service_code,
      actif=excluded.actif;

  PERFORM public.org_log(
    c,'org_poste_save',p_code,
    jsonb_build_object('role',p_role,'parent',p_parent,'actif',p_actif)
  );
END
$function$

CREATE OR REPLACE FUNCTION public.org_sa_role_droit_set(p_commune text, p_role text, p_module text, p_action text, p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  c uuid := public.org_gest(p_commune);
  platform_admin boolean := coalesce(private.is_platform_admin(),false);
  modules text[] := array['cabinet','instr','rapports','cin','cout','actes','dossiers','archives','conseil','citoyens','pub','med','budget','marches','regie','personnel','conges','paie','remun','projets','territoire','patrimoine','civil','params','deleg','org'];
  actions text[] := array['consulter','creer','modifier','supprimer','valider','rejeter','signer','exporter','imprimer','partager','administrer'];
begin
  if not platform_admin and not public.is_super_admin() and not public.org_droit('org','administrer') then raise exception 'Accès refusé'; end if;
  if p_role='maire' or not exists(
    select 1 from public.org_roles r where r.commune_id=c and r.code=p_role and r.actif
  ) then raise exception 'Rôle invalide ou protégé'; end if;
  if not (p_module=any(modules)) or not (p_action=any(actions)) then raise exception 'Module ou action invalide'; end if;
  if p_on then
    if not platform_admin and not public.is_super_admin() and not public.org_droit_propre((select auth.uid()),p_module,p_action) then
      raise exception 'Vous ne pouvez accorder que les droits que vous détenez';
    end if;
    insert into public.org_role_droits(commune_id,role_code,module,action)
    values(c,p_role,p_module,p_action) on conflict do nothing;
  else
    delete from public.org_role_droits
    where commune_id=c and role_code=p_role and module=p_module and action=p_action;
  end if;
  perform public.org_log(c,'org_role_droit',p_role,
    jsonb_build_object('module',p_module,'action',p_action,'accorde',p_on));
end
$function$

CREATE OR REPLACE FUNCTION public.org_sa_role_save(p_commune text, p_code text, p_nom text, p_desc text, p_actif boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid:=public.org_gest(p_commune); platform_admin boolean:=coalesce(private.is_platform_admin(),false); existing_systeme boolean;
begin
  if not platform_admin and not public.is_super_admin() and not public.org_droit('org','administrer') then raise exception 'Accès refusé'; end if;
  if p_code is null or p_code !~ '^[a-z][a-z0-9_]{1,40}$' or p_code='maire' then raise exception 'Code de rôle invalide ou protégé'; end if;
  if length(trim(coalesce(p_nom,'')))<2 then raise exception 'Nom du rôle obligatoire'; end if;
  select systeme into existing_systeme from public.org_roles where commune_id=c and code=p_code for update;
  if coalesce(existing_systeme,false) then raise exception 'Un rôle système ne peut pas être modifié ici'; end if;
  if p_actif is false and exists(select 1 from public.org_postes where commune_id=c and role_code=p_code and actif) then
    raise exception 'Réaffectez d’abord les postes actifs avant de désactiver ce rôle';
  end if;
  insert into public.org_roles(commune_id,code,nom,description,systeme,actif)
  values(c,p_code,trim(p_nom),p_desc,false,coalesce(p_actif,true))
  on conflict(commune_id,code) do update set nom=excluded.nom,description=excluded.description,actif=excluded.actif;
  perform public.org_log(c,'org_role_save',p_code,jsonb_build_object('nom',p_nom,'actif',p_actif));
end
$function$

CREATE OR REPLACE FUNCTION public.org_sa_service_save(p_commune text, p_code text, p_nom text, p_type text, p_parent text, p_responsable text, p_ordre integer, p_actif boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid:=public.org_gest(p_commune);
  pid uuid;
  sid uuid;
  x uuid;
  n integer:=0;
BEGIN
  IF length(trim(coalesce(p_nom,'')))<2 THEN
    RAISE EXCEPTION 'Nom obligatoire';
  END IF;

  IF p_parent IS NOT NULL THEN
    SELECT id INTO pid
    FROM public.services WHERE commune_id=c AND code=p_parent;
    IF pid IS NULL THEN RAISE EXCEPTION 'Service parent introuvable'; END IF;
  END IF;

  SELECT id INTO sid FROM public.services WHERE commune_id=c AND code=p_code;

  x:=pid;
  WHILE x IS NOT NULL AND n<30 LOOP
    IF x=sid THEN RAISE EXCEPTION 'Lien hiérarchique circulaire'; END IF;
    SELECT parent_id INTO x FROM public.services WHERE id=x;
    n:=n+1;
  END LOOP;

  INSERT INTO public.services(
    commune_id,code,nom,type,parent_id,responsable,ordre,actif
  )
  VALUES (
    c,p_code,trim(p_nom),coalesce(p_type,'service'),pid,p_responsable,
    coalesce(p_ordre,0),coalesce(p_actif,true)
  )
  ON CONFLICT(commune_id,code) DO UPDATE
  SET nom=excluded.nom,type=excluded.type,parent_id=excluded.parent_id,
      responsable=excluded.responsable,ordre=excluded.ordre,actif=excluded.actif
  RETURNING id INTO sid;

  PERFORM public.org_log(
    c,'org_service_save',p_code,
    jsonb_build_object('type',p_type,'actif',p_actif)
  );

  RETURN sid;
END
$function$

CREATE OR REPLACE FUNCTION public.org_service_save(p_code text, p_nom text, p_type text, p_parent text, p_responsable text, p_description text, p_actif boolean DEFAULT true, p_ordre integer DEFAULT NULL::integer, p_effectif integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  c uuid:=public.org_commune();
  x text:=p_parent;
  n integer:=0;
  pid uuid;
  sid uuid;
  cur boolean;
BEGIN
  IF c IS NULL OR NOT public.org_droit('org','administrer') THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;
  IF p_code IS NULL OR p_code !~ '^[a-z][a-z0-9_]{1,60}$' THEN
    RAISE EXCEPTION 'Code invalide (minuscules, chiffres, _)';
  END IF;
  IF length(trim(coalesce(p_nom,'')))<2 THEN RAISE EXCEPTION 'Le nom est obligatoire'; END IF;
  IF p_ordre IS NOT NULL AND p_ordre<0 THEN RAISE EXCEPTION 'Ordre invalide'; END IF;
  IF p_effectif IS NOT NULL AND p_effectif<0 THEN RAISE EXCEPTION 'Effectif invalide'; END IF;

  IF p_parent IS NOT NULL THEN
    SELECT id INTO pid FROM public.services WHERE commune_id=c AND code=p_parent;
    IF pid IS NULL THEN RAISE EXCEPTION 'Service parent introuvable'; END IF;

    WHILE x IS NOT NULL AND n<30 LOOP
      IF x=p_code THEN RAISE EXCEPTION 'Lien hiérarchique circulaire'; END IF;
      SELECT p2.code INTO x
      FROM public.services s
      JOIN public.services p2 ON p2.id=s.parent_id
      WHERE s.commune_id=c AND s.code=x;
      n:=n+1;
    END LOOP;
  END IF;

  SELECT id,actif INTO sid,cur
  FROM public.services WHERE commune_id=c AND code=p_code;

  IF sid IS NOT NULL AND coalesce(cur,true) AND NOT coalesce(p_actif,true) THEN
    IF EXISTS(
      SELECT 1 FROM public.org_postes
      WHERE commune_id=c AND service_code=p_code AND coalesce(actif,true)
    ) OR EXISTS(
      SELECT 1 FROM public.org_affectations
      WHERE commune_id=c AND service_code=p_code AND coalesce(actif,true)
    ) OR EXISTS(
      SELECT 1 FROM public.services
      WHERE commune_id=c AND parent_id=sid AND coalesce(actif,true)
    ) THEN
      RAISE EXCEPTION 'Service utilisé (postes, agents ou sous-services actifs) : désactivation refusée';
    END IF;
  END IF;

  INSERT INTO public.services(
    commune_id,code,nom,type,parent_id,responsable,description,
    actif,ordre,effectif
  )
  VALUES(
    c,p_code,trim(p_nom),coalesce(p_type,'service'),pid,
    nullif(trim(p_responsable),''),nullif(trim(p_description),''),
    coalesce(p_actif,true),coalesce(p_ordre,0),p_effectif
  )
  ON CONFLICT(commune_id,code) DO UPDATE
  SET nom=excluded.nom,type=excluded.type,parent_id=excluded.parent_id,
      responsable=excluded.responsable,description=excluded.description,
      actif=excluded.actif,ordre=coalesce(p_ordre,public.services.ordre),
      effectif=coalesce(p_effectif,public.services.effectif);

  PERFORM public.org_log(
    c,'org_service_save',p_code,
    jsonb_build_object('parent',p_parent,'actif',p_actif)
  );
END
$function$

CREATE OR REPLACE FUNCTION public.org_sync_user_affectations(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role requis'; end if;
  select commune_id into c from public.profiles where id=p_user and coalesce(actif,true);
  if c is null then raise exception 'Compte actif introuvable'; end if;
  if exists(select 1 from public.personnel where user_id=p_user and commune_id=c and actif) then
    update public.org_affectations oa set service_code=(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),fin=a.fin,actif=(a.fin is null or a.fin>=current_date)
    from public.org_agent_affectations a join public.personnel pe on pe.id=a.personnel_id
    where oa.commune_id=c and oa.user_id=p_user and a.commune_id=c and pe.commune_id=c and pe.user_id=p_user and pe.actif and oa.poste_code=a.poste_code and oa.debut=a.debut;
    insert into public.org_affectations(commune_id,user_id,poste_code,service_code,debut,fin,actif,created_by)
    select c,p_user,a.poste_code,(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),a.debut,a.fin,(a.fin is null or a.fin>=current_date),null
    from public.org_agent_affectations a join public.personnel pe on pe.id=a.personnel_id
    where a.commune_id=c and pe.commune_id=c and pe.user_id=p_user and pe.actif
      and not exists(select 1 from public.org_affectations oa where oa.commune_id=c and oa.user_id=p_user and oa.poste_code=a.poste_code and oa.debut=a.debut);
  end if;
  if exists(select 1 from public.adjoints where user_id=p_user and commune_id=c and actif) then
    update public.org_affectations oa set service_code=(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),fin=a.fin,actif=(a.fin is null or a.fin>=current_date)
    from public.org_agent_affectations a join public.adjoints ad on ad.id=a.adjoint_id
    where oa.commune_id=c and oa.user_id=p_user and a.commune_id=c and ad.commune_id=c and ad.user_id=p_user and ad.actif and oa.poste_code=a.poste_code and oa.debut=a.debut;
    insert into public.org_affectations(commune_id,user_id,poste_code,service_code,debut,fin,actif,created_by)
    select c,p_user,a.poste_code,(select s.code from public.services s where s.id=a.service_id and s.commune_id=c),a.debut,a.fin,(a.fin is null or a.fin>=current_date),null
    from public.org_agent_affectations a join public.adjoints ad on ad.id=a.adjoint_id
    where a.commune_id=c and ad.commune_id=c and ad.user_id=p_user and ad.actif
      and not exists(select 1 from public.org_affectations oa where oa.commune_id=c and oa.user_id=p_user and oa.poste_code=a.poste_code and oa.debut=a.debut);
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.paie_generer(p_mois date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid := private.paie_garde(array['maire','rh'],'creer'); pid uuid; st text; m date := date_trunc('month', p_mois)::date;
begin
  select id, statut into pid, st from public.paies where commune_id=c and mois=m;
  if pid is not null and st <> 'brouillon' then raise exception 'Cette paie n''est plus modifiable'; end if;
  if pid is null then insert into public.paies(commune_id,mois) values (c,m) returning id into pid;
  else delete from public.paie_lignes where paie_id=pid; end if;
  insert into public.paie_lignes(commune_id,paie_id,personnel_id,brut,retenues)
   select c,pid,p.id,coalesce(r.salaire_base,0)+coalesce(r.indemnites,0),coalesce(r.retenues,0)
   from public.personnel p left join public.remunerations r on r.personnel_id=p.id
   where p.commune_id=c and p.actif and (p.date_sortie is null or p.date_sortie>=m);
  perform private.paie_totaux(pid); return pid;
end $function$

CREATE OR REPLACE FUNCTION public.paie_maj_ligne(p_ligne uuid, p_brut numeric, p_retenues numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid := private.paie_garde(array['maire','rh'],'modifier'); pid uuid;
begin
  select l.paie_id into pid from public.paie_lignes l join public.paies p on p.id=l.paie_id where l.id=p_ligne and l.commune_id=c and p.statut='brouillon';
  if pid is null then raise exception 'Ligne introuvable ou paie non modifiable'; end if;
  if p_brut<0 or p_retenues<0 or p_retenues>p_brut then raise exception 'Montants invalides'; end if;
  update public.paie_lignes set brut=p_brut, retenues=p_retenues where id=p_ligne;
  perform private.paie_totaux(pid);
end $function$

CREATE OR REPLACE FUNCTION public.paie_ordonnancer(p_paie uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid := private.paie_garde(array['maire'],'signer'); m date;
begin
  if exists(select 1 from public.paies where id=p_paie and commune_id=c and statut='valide' and valide_par is not distinct from auth.uid()) then
    raise exception 'Séparation des tâches : la personne qui a validé la paie ne peut pas l''ordonnancer' using errcode='42501'; end if;
  update public.paies set statut='ordonnance', ordonne_par=auth.uid(), ordonne_le=now() where id=p_paie and commune_id=c and statut='valide' returning mois into m;
  if not found then raise exception 'La paie doit être validée avant ordonnancement'; end if;
  insert into public.decisions(commune_id,type,objet,created_by) values (c,'Décision','Ordonnancement de la paie du personnel : '||to_char(m,'MM/YYYY'),auth.uid());
end $function$

CREATE OR REPLACE FUNCTION public.paie_payer(p_paie uuid, p_date date, p_ref text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c uuid := private.paie_garde(array['maire','finances']);
begin
  if coalesce(btrim(p_ref),'')='' or p_date is null then raise exception 'Date et référence du paiement obligatoires'; end if;
  update public.paies set statut='paye', date_paiement=p_date, reference_paiement=btrim(p_ref), paye_par=auth.uid() where id=p_paie and commune_id=c and statut='ordonnance';
  if not found then raise exception 'La paie doit être ordonnancée avant paiement'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.relancer_instruction(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  i public.instructions;
BEGIN
  IF auth.uid() IS NULL
     OR NOT (
       private.is_platform_admin()
       OR coalesce(private.my_role() IN ('maire','secretariat','super_admin'), false)
     ) THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  SELECT * INTO i
  FROM public.instructions
  WHERE id = p_id;

  IF i.id IS NULL
     OR (
       i.commune_id IS DISTINCT FROM private.my_commune()
       AND NOT private.is_platform_admin()
     ) THEN
    RAISE EXCEPTION 'Instruction introuvable';
  END IF;

  IF i.adjoint_id IS NOT NULL THEN
    PERFORM private.notifier_adjoint(
      i.commune_id,i.adjoint_id,'Relance',
      i.reference || ' : ' || i.objet,'instr'
    );
  END IF;

  IF i.service IS NOT NULL AND i.service NOT IN ('externe','adjoint') THEN
    PERFORM private.notifier_role(
      i.commune_id,i.service,'Relance',
      i.reference || ' : ' || i.objet,'s_instr'
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.sa_creer_sauvegarde(p_commune text, p_nom text, p_type text DEFAULT 'manuelle'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t text; v jsonb; c jsonb := '{}'::jsonb; cnt jsonb := '{}'::jsonb; sid uuid;
begin
  perform public._garde(p_commune);
  foreach t in array array['indicateurs','parametres_systeme','permissions_roles','profiles','rdv','courrier','demandes','publications',
    'medias','projets','finances','delegations','adjoints','reunions','instructions','rapports','deliberations','actes','sessions_conseil',
    'services','dossiers','archives','notifications','documents','conseillers'] loop
    if to_regclass('public.' || t) is not null and exists (
      select 1 from information_schema.columns where table_schema = 'public' and table_name = t and column_name = 'commune_id') then
      execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.commune_id::text = $1'
        || case t when 'courrier' then ' and coalesce(x.confidentiel, false) = false'
                  when 'documents' then ' and coalesce(x.confidentialite, '''') <> ''confidentiel'''
                  else '' end, t) into v using p_commune;
      c := c || jsonb_build_object(t, v);
      cnt := cnt || jsonb_build_object(t, jsonb_array_length(v));
    end if;
  end loop;
  insert into public.sauvegardes (commune_id, nom, type, taille, tables, contenu, created_by, created_by_email)
  values (p_commune, coalesce(nullif(trim(left(p_nom, 120)), ''), 'Sauvegarde ' || to_char(now(), 'DD/MM/YYYY HH24:MI')), p_type,
          octet_length(c::text), cnt, c, auth.uid(), (select email from auth.users where id = auth.uid()))
  returning id into sid;
  perform public._audit(p_commune, 'backup_create', sid::text, jsonb_build_object('type', p_type, 'tables', cnt));
  return sid;
end $function$

CREATE OR REPLACE FUNCTION public.sa_incident_creer(p_commune text, p_titre text, p_gravite text, p_description text, p_source text DEFAULT 'manuel'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare iid uuid;
begin
  perform public._garde(p_commune);
  if nullif(trim(p_titre), '') is null then raise exception 'Titre requis'; end if;
  insert into public.incidents (commune_id, titre, gravite, description, source, created_by, created_by_email)
  values (p_commune, trim(p_titre), p_gravite, nullif(trim(p_description), ''), coalesce(p_source, 'manuel'), auth.uid(),
          (select email from auth.users where id = auth.uid())) returning id into iid;
  perform public._audit(p_commune, 'incident_create', iid::text, jsonb_build_object('titre', p_titre, 'gravite', p_gravite));
  return iid;
end $function$

CREATE OR REPLACE FUNCTION public.sa_reset_permissions_user(p_commune text, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare em text;
begin
  perform public._garde(p_commune);
