end $function$

CREATE OR REPLACE FUNCTION public.sa_restaurer(p_commune text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  s public.sauvegardes;
  t text;
  item jsonb;
  done jsonb := '[]'::jsonb;
BEGIN
  PERFORM public._garde(p_commune);

  SELECT * INTO s
  FROM public.sauvegardes
  WHERE id=p_id AND commune_id=p_commune
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sauvegarde introuvable';
  END IF;

  IF jsonb_typeof(s.contenu)<>'object' THEN
    RAISE EXCEPTION 'Contenu de sauvegarde invalide';
  END IF;

  -- Contrôle préalable intégral : aucune ligne d'une autre commune ne doit
  -- pouvoir être réinjectée depuis un contenu de sauvegarde altéré.
  FOREACH t IN ARRAY ARRAY['indicateurs','parametres_systeme','permissions_roles'] LOOP
    IF s.contenu ? t THEN
      IF jsonb_typeof(s.contenu->t)<>'array' THEN
        RAISE EXCEPTION 'Format de sauvegarde invalide pour %',t;
      END IF;

      FOR item IN SELECT value FROM jsonb_array_elements(s.contenu->t) AS e(value) LOOP
        IF jsonb_typeof(item)<>'object'
           OR item->>'commune_id' IS DISTINCT FROM p_commune THEN
          RAISE EXCEPTION 'Ligne de sauvegarde hors périmètre communal dans %',t;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  -- Point de restauration préalable conservé dans la même transaction.
  PERFORM public.sa_creer_sauvegarde(
    p_commune,
    'Avant restauration ' || to_char(now(),'DD/MM/YYYY HH24:MI'),
    'automatique'
  );

  FOREACH t IN ARRAY ARRAY['indicateurs','parametres_systeme','permissions_roles'] LOOP
    IF s.contenu ? t AND to_regclass('public.'||t) IS NOT NULL THEN
      EXECUTE format('DELETE FROM public.%I WHERE commune_id::text=$1',t)
      USING p_commune;

      EXECUTE format(
        'INSERT INTO public.%I SELECT * FROM jsonb_populate_recordset(null::public.%I,$1)',
        t,t
      )
      USING s.contenu->t;

      done:=done||to_jsonb(t);
    END IF;
  END LOOP;

  PERFORM public._audit(
    p_commune,'backup_restore',p_id::text,
    jsonb_build_object('tables',done)
  );

  RETURN jsonb_build_object('restaurees',done);
END
$function$

CREATE OR REPLACE FUNCTION public.sa_set_image(p_commune text, p_cle text, p_chemin text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old text; n int;
begin
  perform public._garde(p_commune);
  if p_cle not in ('blason', 'photo_maire', 'bandeau') then raise exception 'Image inconnue'; end if;
  if left(p_chemin, length(p_commune) + 1) <> p_commune || '/' then raise exception 'Chemin invalide'; end if;
  execute format('select %I from public.indicateurs where commune_id::text = $1', p_cle) into old using p_commune;
  execute format('update public.indicateurs set %I = $1 where commune_id::text = $2', p_cle) using p_chemin, p_commune;
  get diagnostics n = row_count;
  if n = 0 then
    execute format('insert into public.indicateurs (commune_id, %I) select c.id, $1 from public.communes c where c.id::text = $2', p_cle)
      using p_chemin, p_commune;
  end if;
  perform public._audit(p_commune, 'image_set', p_cle, jsonb_build_object('chemin', p_chemin));
  return old;
end $function$

CREATE OR REPLACE FUNCTION public.sa_set_param(p_commune text, p_cle text, p_valeur jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public._garde(p_commune);
  if p_cle not in ('maintenance', 'modules', 'idle_min', 'mdp_min') then raise exception 'Paramètre inconnu'; end if;
  if p_cle = 'idle_min' and (jsonb_typeof(p_valeur) <> 'number' or (p_valeur #>> '{}')::numeric not between 5 and 480) then
    raise exception 'Inactivité : 5 à 480 minutes'; end if;
  if p_cle = 'mdp_min' and (jsonb_typeof(p_valeur) <> 'number' or (p_valeur #>> '{}')::numeric not between 8 and 64) then
    raise exception 'Mot de passe : 8 à 64 caractères'; end if;
  if p_cle in ('maintenance', 'modules') and jsonb_typeof(p_valeur) <> 'object' then raise exception 'Valeur invalide'; end if;
  insert into public.parametres_systeme (commune_id, cle, valeur, updated_by) values (p_commune, p_cle, p_valeur, auth.uid())
  on conflict (commune_id, cle) do update set valeur = excluded.valeur, updated_at = now(), updated_by = auth.uid();
  perform public._audit(p_commune, 'param_set', p_cle, jsonb_build_object('valeur', p_valeur));
end $function$

CREATE OR REPLACE FUNCTION public.sa_set_permission(p_commune text, p_role text, p_cle text, p_autorise boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public._garde(p_commune);
  if p_role not in ('maire','adjoint','cabinet','secretariat','finances','rh','etat_civil','technique','agent') then raise exception 'Rôle non modifiable'; end if;
  if p_cle <> all (private.perm_valides()) then raise exception 'Permission invalide'; end if;
  insert into public.permissions_roles (commune_id, role, cle, autorise, updated_by) values (p_commune, p_role, p_cle, p_autorise, auth.uid())
  on conflict (commune_id, role, cle) do update set autorise = excluded.autorise, updated_at = now(), updated_by = auth.uid();
  perform public._audit(p_commune, 'perm_set', p_role, jsonb_build_object('cle', p_cle, 'autorise', p_autorise));
end $function$

CREATE OR REPLACE FUNCTION public.sa_set_permission_user(p_commune text, p_user uuid, p_cle text, p_autorise boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text; em text;
begin
  perform public._garde(p_commune);
  if p_cle <> all (private.perm_valides()) then raise exception 'Permission invalide'; end if;
  select role into r from public.profiles where id=p_user and commune_id::text=p_commune;
  if r is null then raise exception 'Compte introuvable dans cette commune'; end if;
  if r in ('super_admin','adjoint','secretariat') then raise exception 'Compte non modifiable'; end if;
  insert into public.permissions_utilisateurs(commune_id,user_id,cle,autorise,updated_by) values (p_commune,p_user,p_cle,p_autorise,auth.uid())
  on conflict (commune_id,user_id,cle) do update set autorise=excluded.autorise, updated_at=now(), updated_by=auth.uid();
  select email into em from auth.users where id=p_user;
  perform public._audit(p_commune,'perm_user_set',em,jsonb_build_object('cle',p_cle,'autorise',p_autorise));
end $function$

CREATE OR REPLACE FUNCTION public.sa_stats(p_commune text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  r jsonb;
  t text;
  n bigint;
  vol jsonb := '{}'::jsonb;
BEGIN
  PERFORM public._garde(p_commune);

  FOREACH t IN ARRAY ARRAY[
    'demandes','courrier','deliberations','actes','projets',
    'publications','medias','rdv','reunions'
  ] LOOP
    IF to_regclass('public.' || t) IS NOT NULL
       AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema='public'
           AND table_name=t
           AND column_name='commune_id'
       ) THEN
      EXECUTE format(
        'SELECT count(*) FROM public.%I WHERE commune_id::text = $1',
        t
      ) INTO n USING p_commune;
      vol := vol || jsonb_build_object(t,n);
    END IF;
  END LOOP;

  SELECT jsonb_build_object(
    'users_total', (
      SELECT count(*) FROM public.profiles p
      WHERE p.commune_id::text = p_commune
    ),
    'users_actifs', (
      SELECT count(*) FROM public.profiles p
      WHERE p.commune_id::text = p_commune AND p.actif
    ),
    'users_30j', (
      SELECT count(*)
      FROM public.profiles p
      JOIN auth.users u ON u.id=p.id
      WHERE p.commune_id::text = p_commune
        AND u.created_at > now() - interval '30 days'
    ),
    'par_role', (
      SELECT coalesce(jsonb_object_agg(role,c),'{}'::jsonb)
      FROM (
        SELECT p.role::text AS role,count(*) c
        FROM public.profiles p
        WHERE p.commune_id::text = p_commune
        GROUP BY 1
      ) x
    ),
    'derniere_sauvegarde', (
      SELECT max(created_at) FROM public.sauvegardes
      WHERE commune_id = p_commune
    ),
    'nb_sauvegardes', (
      SELECT count(*) FROM public.sauvegardes
      WHERE commune_id = p_commune
    ),
    'incidents_ouverts', (
      SELECT count(*) FROM public.incidents
      WHERE commune_id = p_commune AND statut <> 'resolu'
    ),
    'audit_24h', (
      SELECT count(*) FROM public.journal_audit
      WHERE commune_id = p_commune
        AND created_at > now() - interval '24 hours'
    ),
    'taille_db', pg_database_size(current_database()),
    'volumes', vol
  ) INTO r;

  RETURN r;
END;
$function$

CREATE OR REPLACE FUNCTION public.sa_supprimer_sauvegarde(p_commune text, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  n integer;
BEGIN
  PERFORM public._garde(p_commune);

  DELETE FROM public.sauvegardes
  WHERE id=p_id AND commune_id=p_commune;

  GET DIAGNOSTICS n=ROW_COUNT;

  IF n=0 THEN
    RAISE EXCEPTION 'Sauvegarde introuvable dans cette commune';
  END IF;

  PERFORM public._audit(p_commune,'backup_delete',p_id::text,NULL);
END
$function$

CREATE OR REPLACE FUNCTION public.saas_abo_maj(p_commune uuid, p_plan text, p_statut text, p_prix_perso integer, p_fin_essai date, p_echeance date, p_options jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  o jsonb;
  total_options bigint := 0;
BEGIN
  PERFORM private.pgarde(ARRAY['proprietaire','admin','finance']);

  IF p_commune IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.communes WHERE id=p_commune
  ) THEN
    RAISE EXCEPTION 'Mairie introuvable';
  END IF;

  IF p_plan IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.plans WHERE code=p_plan
  ) THEN
    RAISE EXCEPTION 'Offre inconnue';
  END IF;

  IF p_statut IS NULL OR p_statut NOT IN ('essai','actif','impaye','suspendu','resilie') THEN
    RAISE EXCEPTION 'Statut invalide';
  END IF;

  IF p_prix_perso IS NOT NULL AND p_prix_perso<0 THEN
    RAISE EXCEPTION 'Prix invalide';
  END IF;

  p_options:=coalesce(p_options,'[]'::jsonb);

  IF jsonb_typeof(p_options)<>'array' THEN
    RAISE EXCEPTION 'Options invalides : un tableau est requis';
  END IF;

  IF jsonb_array_length(p_options)>20 THEN
    RAISE EXCEPTION '20 options maximum par abonnement';
  END IF;

  FOR o IN SELECT value FROM jsonb_array_elements(p_options) AS x(value) LOOP
    IF jsonb_typeof(o)<>'object'
       OR coalesce(trim(o->>'nom'),'')=''
       OR char_length(trim(o->>'nom'))>100
       OR coalesce(o->>'prix','') !~ '^[0-9]{1,9}$' THEN
      RAISE EXCEPTION 'Option invalide : nom (100 caractères max) et prix entier requis';
    END IF;

    total_options:=total_options+(o->>'prix')::bigint;
    IF total_options>2147483647 THEN
      RAISE EXCEPTION 'Le total des options dépasse le montant maximal autorisé';
    END IF;
  END LOOP;

  INSERT INTO public.abonnements(
    commune_id,plan_code,statut,fin_essai,prochaine_echeance,prix_perso,options
  )
  VALUES (
    p_commune,p_plan,p_statut,p_fin_essai,p_echeance,p_prix_perso,p_options
  )
  ON CONFLICT (commune_id) DO UPDATE
  SET plan_code=excluded.plan_code,
      statut=excluded.statut,
      fin_essai=excluded.fin_essai,
      prochaine_echeance=excluded.prochaine_echeance,
      prix_perso=excluded.prix_perso,
      options=excluded.options;

  PERFORM private.paudit(
    'abo_maj',p_commune,
    jsonb_build_object(
      'plan',p_plan,'statut',p_statut,
      'prix_perso',p_prix_perso,'options_count',jsonb_array_length(p_options)
    )
  );
END
$function$

CREATE OR REPLACE FUNCTION public.saas_acces_ouvrir(p_commune uuid, p_motif text, p_minutes integer DEFAULT 60)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i uuid; begin
 perform private.pgarde(array['proprietaire','admin','support']);
 if coalesce(length(trim(p_motif)),0)<10 then raise exception 'Motif détaillé obligatoire (10 caractères min.)'; end if;
 if p_minutes<5 or p_minutes>240 then raise exception 'Durée : 5 à 240 minutes'; end if;
 if not exists(select 1 from public.communes where id=p_commune) then raise exception 'Mairie introuvable'; end if;
 insert into public.acces_techniques(commune_id,admin_id,motif,expire_le) values (p_commune,(select auth.uid()),trim(p_motif),now()+make_interval(mins=>p_minutes)) returning id into i;
 perform private.paudit('acces_ouvert',p_commune,jsonb_build_object('acces',i,'minutes',p_minutes,'motif',p_motif));
 return i; end $function$

CREATE OR REPLACE FUNCTION public.saas_creer_commune(p_nom text, p_slug text, p_plan text, p_essai_jours integer, p_admin uuid, p_admin_nom text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cid uuid; s text:=lower(trim(p_slug));
begin
  perform private.pgarde(array['proprietaire','admin']);
  if coalesce(trim(p_nom),'')='' then raise exception 'Nom obligatoire'; end if;
  if s !~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$' then raise exception 'Identifiant invalide (3 à 40 caractères : a-z, 0-9, tiret)'; end if;
  if s=any(array['www','app','saas','admin','api','mairie','citoyen','mail','static','cdn','support']) then raise exception 'Identifiant réservé'; end if;
  if not exists(select 1 from public.plans where code=p_plan and actif) then raise exception 'Offre inconnue'; end if;
  if coalesce(p_essai_jours,0)<0 or coalesce(p_essai_jours,0)>90 then raise exception 'Essai : 0 à 90 jours'; end if;
  if p_admin is null or not exists(select 1 from auth.users where id=p_admin) then raise exception 'Compte administrateur municipal introuvable'; end if;
  perform 1 from public.platform_admins where user_id=p_admin for key share;
  if found then raise exception 'Un compte administrateur plateforme ne peut pas être administrateur municipal'; end if;
  perform 1 from public.profiles where id=p_admin for update;
  if found and exists(select 1 from public.profiles where id=p_admin and (commune_id is not null or coalesce(role::text,'citoyen')<>'citoyen')) then
    raise exception 'Ce compte possède déjà une affectation municipale ou un rôle privilégié';
  end if;
  insert into public.communes(nom,slug,statut,sous_domaine,admin_principal)
  values(trim(p_nom),s,case when coalesce(p_essai_jours,0)>0 then 'essai' else 'actif' end,s,p_admin)
  returning id into cid;
  insert into public.profiles(id,role,commune_id,nom,actif)
  values(p_admin,'maire',cid,p_admin_nom,false)
  on conflict(id) do update set role='maire',commune_id=excluded.commune_id,nom=excluded.nom,actif=false
  where public.profiles.role='citoyen' and public.profiles.commune_id is null;
  if not found then raise exception 'Impossible d’affecter le compte comme maire'; end if;
  insert into public.indicateurs(commune_id)
  select cid where not exists(select 1 from public.indicateurs where commune_id=cid);
  insert into public.abonnements(commune_id,plan_code,statut,fin_essai,prochaine_echeance)
  values(cid,p_plan,case when coalesce(p_essai_jours,0)>0 then 'essai' else 'actif' end,
    case when p_essai_jours>0 then current_date+p_essai_jours end,current_date+coalesce(nullif(p_essai_jours,0),30));
  perform private.paudit('commune_creer',cid,jsonb_build_object('nom',p_nom,'slug',s,'plan',p_plan,'essai',p_essai_jours,'admin_inactif',true));
  return cid;
end
$function$

CREATE OR REPLACE FUNCTION public.saas_facture_annuler(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f public.factures;
begin
 perform private.pgarde(array['proprietaire','admin','finance']);
 select * into f from public.factures where id=p_id for update;
 if not found then raise exception 'Facture introuvable'; end if;
 if f.statut='payee' or exists(select 1 from public.paiements where facture_id=p_id) then raise exception 'Facture déjà encaissée (totalement ou partiellement)'; end if;
 update public.factures set statut='annulee' where id=p_id;
 perform private.paudit('facture_annuler',f.commune_id,jsonb_build_object('numero',f.numero));
end $function$

CREATE OR REPLACE FUNCTION public.saas_facture_creer(p_commune uuid, p_periode text, p_montant integer DEFAULT NULL::integer, p_echeance date DEFAULT NULL::date)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  a public.abonnements;
  m integer;
  n text;
BEGIN
  PERFORM private.pgarde(ARRAY['proprietaire','admin','finance']);

  IF p_commune IS NULL THEN
    RAISE EXCEPTION 'Commune obligatoire';
  END IF;

  IF p_periode IS NULL OR p_periode !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'Période invalide (AAAA-MM)';
  END IF;

  -- Sérialise la création pour une même commune et une même période.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_commune::text || ':' || p_periode,0)
  );

  SELECT * INTO a
  FROM public.abonnements
  WHERE commune_id=p_commune
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Aucun abonnement pour cette mairie';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.factures
    WHERE commune_id=p_commune
      AND periode=p_periode
      AND statut<>'annulee'
  ) THEN
    RAISE EXCEPTION 'Une facture existe déjà pour cette période';
  END IF;

  m:=coalesce(p_montant,private.prix_abo(a));

  IF m IS NULL OR m<=0 THEN
    RAISE EXCEPTION 'Montant nul ou invalide : renseignez un montant positif';
  END IF;

  n:='FAC-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.facture_seq')::text,5,'0');

  INSERT INTO public.factures(commune_id,numero,periode,montant,echeance)
  VALUES (p_commune,n,p_periode,m,coalesce(p_echeance,current_date+15));

  PERFORM private.paudit(
    'facture_creer',p_commune,
    jsonb_build_object('numero',n,'montant',m)
  );

  RETURN n;
END
$function$

CREATE OR REPLACE FUNCTION public.saas_modules_set(p_commune uuid, p_modules jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k text;
begin
 perform private.pgarde(array['proprietaire','admin']);
 if jsonb_typeof(p_modules)<>'object' then raise exception 'Valeur invalide'; end if;
 for k in select jsonb_object_keys(p_modules) loop
  if k not in ('cabinet','adjoints','administration','developpement','conseil','citoyens','pilotage','finances','portail_adjoint','portail_secretariat') then raise exception 'Module inconnu : %',k; end if;
  if jsonb_typeof(p_modules->k)<>'boolean' then raise exception 'Valeur invalide pour %',k; end if;
 end loop;
 if not exists(select 1 from public.communes where id=p_commune) then raise exception 'Mairie introuvable'; end if;
 insert into public.parametres_systeme(commune_id,cle,valeur,updated_by) values (p_commune::text,'modules',p_modules,(select auth.uid()))
 on conflict (commune_id,cle) do update set valeur=excluded.valeur,updated_at=now(),updated_by=(select auth.uid());
 perform private.paudit('modules_maj',p_commune,p_modules);
end $function$

CREATE OR REPLACE FUNCTION public.saas_paiement_enreg(p_facture uuid, p_montant integer, p_mode text, p_reference text, p_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  f public.factures;
  paid integer;
  date_paiement date;
  ref text;
BEGIN
  PERFORM private.pgarde(ARRAY['proprietaire','admin','finance']);

  IF p_facture IS NULL THEN
    RAISE EXCEPTION 'Facture obligatoire';
  END IF;

  IF p_mode IS NULL OR p_mode NOT IN ('wave','orange_money','virement','especes','autre') THEN
    RAISE EXCEPTION 'Mode de paiement invalide';
  END IF;

  date_paiement:=coalesce(p_date,current_date);
  IF date_paiement>current_date THEN
    RAISE EXCEPTION 'La date du paiement ne peut pas être future';
  END IF;

  ref:=nullif(trim(p_reference),'');
  IF ref IS NOT NULL AND char_length(ref)>200 THEN
    RAISE EXCEPTION 'Référence de paiement trop longue (200 caractères maximum)';
  END IF;

  SELECT * INTO f
  FROM public.factures
  WHERE id=p_facture
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Facture introuvable';
  END IF;

  IF f.statut NOT IN ('emise','impayee') THEN
    RAISE EXCEPTION 'Seules les factures émises ou impayées peuvent recevoir un paiement';
  END IF;

  SELECT coalesce(sum(montant),0) INTO paid
  FROM public.paiements
  WHERE facture_id=p_facture;

  IF p_montant IS NULL OR p_montant<=0 OR p_montant>f.montant-paid THEN
    RAISE EXCEPTION 'Montant invalide (reste à payer : % FCFA)',f.montant-paid;
  END IF;

  INSERT INTO public.paiements(
    facture_id,commune_id,montant,mode,reference,recu_le,saisi_par
  )
  VALUES (
    p_facture,f.commune_id,p_montant,p_mode,ref,date_paiement,(SELECT auth.uid())
  );

  IF paid+p_montant>=f.montant THEN
    UPDATE public.factures SET statut='payee' WHERE id=p_facture;

    UPDATE public.abonnements
    SET statut=CASE WHEN statut IN ('essai','impaye') THEN 'actif' ELSE statut END,
        prochaine_echeance=(
          greatest(coalesce(prochaine_echeance,current_date),current_date)
          + interval '1 month'
        )::date
    WHERE commune_id=f.commune_id
      AND statut NOT IN ('suspendu','resilie');

    UPDATE public.communes
    SET statut='actif'
    WHERE id=f.commune_id AND statut='essai';
  END IF;

  PERFORM private.paudit(
    'paiement',f.commune_id,
    jsonb_build_object('numero',f.numero,'montant',p_montant,'mode',p_mode)
  );
END
$function$

CREATE OR REPLACE FUNCTION public.saas_relances()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a int; b int; c int;
begin
 perform private.pgarde(array['proprietaire','admin','finance']);
 update public.factures set statut='impayee' where statut='emise' and echeance<current_date; get diagnostics a=row_count;
 update public.abonnements x set statut='impaye' where x.statut='actif' and exists(select 1 from public.factures f where f.commune_id=x.commune_id and f.statut='impayee'); get diagnostics b=row_count;
 select count(*) into c from public.abonnements where statut='essai' and fin_essai<current_date;
 if a+b>0 then perform private.paudit('relances',null,jsonb_build_object('factures',a,'abonnements',b)); end if;
 return jsonb_build_object('factures_impayees',a,'abonnements_impayes',b,'essais_expires',c);
end $function$

CREATE OR REPLACE FUNCTION public.saas_set_statut(p_commune uuid, p_statut text, p_motif text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform private.pgarde(array['proprietaire','admin']);
 if p_statut not in ('actif','essai','suspendu','resilie') then raise exception 'Statut invalide'; end if;
 if p_statut in ('suspendu','resilie') and coalesce(length(trim(p_motif)),0)<5 then raise exception 'Motif obligatoire'; end if;
 update public.communes set statut=p_statut,suspendu_motif=case when p_statut in ('suspendu','resilie') then p_motif end where id=p_commune;
 if not found then raise exception 'Mairie introuvable'; end if;
 update public.abonnements set statut=case p_statut when 'suspendu' then 'suspendu' when 'resilie' then 'resilie' when 'essai' then 'essai' else 'actif' end where commune_id=p_commune;
 perform private.paudit('commune_statut',p_commune,jsonb_build_object('statut',p_statut,'motif',p_motif));
end $function$
